"use client"

import { useEffect, useRef, useState } from "react"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { CheckCircle, Clock, AlertCircle } from "lucide-react"

interface PresentStudent {
  id: number
  name: string
  rollNo: string
  timestamp: string
}

export default function AttendanceMonitor() {
  const videoRef = useRef<HTMLVideoElement>(null)
  const [presentStudents, setPresentStudents] = useState<PresentStudent[]>([
    { id: 1, name: "Ahmed Hassan", rollNo: "001", timestamp: "09:02 AM" },
    { id: 2, name: "Fatima Khan", rollNo: "002", timestamp: "09:05 AM" },
    { id: 3, name: "Muhammad Ali", rollNo: "003", timestamp: "09:08 AM" },
  ])
  const [recognizedStudent, setRecognizedStudent] = useState<PresentStudent | null>(null)
  const [cameraError, setCameraError] = useState<string | null>(null)
  const [cameraLoading, setCameraLoading] = useState(true)

  useEffect(() => {
    const startCamera = async () => {
      try {
        setCameraLoading(true)
        setCameraError(null)
        const stream = await navigator.mediaDevices.getUserMedia({
          video: { facingMode: "user" },
          audio: false,
        })
        if (videoRef.current) {
          videoRef.current.srcObject = stream
        }
      } catch (error) {
        let errorMessage = "Unable to access camera"
        if (error instanceof DOMException) {
          if (error.name === "NotAllowedError") {
            errorMessage = "Camera permission denied. Please allow camera access in your browser settings."
          } else if (error.name === "NotFoundError") {
            errorMessage = "No camera device found on this system"
          } else if (error.name === "NotReadableError") {
            errorMessage = "Camera is being used by another application"
          }
        }
        setCameraError(errorMessage)
        console.error("[v0] Camera error:", error)
      } finally {
        setCameraLoading(false)
      }
    }

    startCamera()

    return () => {
      if (videoRef.current?.srcObject) {
        const tracks = (videoRef.current.srcObject as MediaStream).getTracks()
        tracks.forEach((track) => track.stop())
      }
    }
  }, [])

  // Simulate recognition
  useEffect(() => {
    const timer = setInterval(() => {
      const randomStudent: PresentStudent = {
        id: Math.floor(Math.random() * 287),
        name: ["Hassan Ahmed", "Zainab Ali", "Omar Khan", "Noor Hassan"][Math.floor(Math.random() * 4)],
        rollNo: String(Math.floor(Math.random() * 287) + 1).padStart(3, "0"),
        timestamp: new Date().toLocaleTimeString(),
      }
      setRecognizedStudent(randomStudent)

      if (!presentStudents.find((s) => s.rollNo === randomStudent.rollNo)) {
        setPresentStudents((prev) => [randomStudent, ...prev])
      }

      setTimeout(() => setRecognizedStudent(null), 3000)
    }, 8000)

    return () => clearInterval(timer)
  }, [presentStudents])

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
      {/* Camera Feed */}
      <div className="lg:col-span-2 space-y-4">
        <Card className="bg-card border-border overflow-hidden">
          <CardHeader>
            <CardTitle className="text-foreground flex items-center gap-2">
              <Camera size={20} className="text-primary" />
              Live Camera Feed
            </CardTitle>
          </CardHeader>
          <CardContent className="p-0">
            <div className="bg-background rounded-lg overflow-hidden border-2 border-border relative">
              {cameraError ? (
                <div className="w-full aspect-video bg-muted flex flex-col items-center justify-center gap-3">
                  <AlertCircle size={48} className="text-destructive" />
                  <div className="text-center px-4">
                    <p className="text-foreground font-medium mb-1">Camera Not Available</p>
                    <p className="text-sm text-muted-foreground">{cameraError}</p>
                  </div>
                </div>
              ) : cameraLoading ? (
                <div className="w-full aspect-video bg-muted flex items-center justify-center">
                  <div className="text-center">
                    <div className="w-8 h-8 border-4 border-primary border-t-transparent rounded-full animate-spin mx-auto mb-2" />
                    <p className="text-sm text-muted-foreground">Initializing camera...</p>
                  </div>
                </div>
              ) : (
                <video ref={videoRef} autoPlay playsInline className="w-full aspect-video object-cover" />
              )}
              {recognizedStudent && (
                <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/40 backdrop-blur-sm">
                  <div className="text-center text-white">
                    <CheckCircle size={48} className="mx-auto mb-2 text-green-400" />
                    <p className="text-2xl font-bold">{recognizedStudent.name}</p>
                    <p className="text-lg text-gray-200">Roll: {recognizedStudent.rollNo}</p>
                  </div>
                </div>
              )}
            </div>
          </CardContent>
        </Card>

        {/* Recognition Status */}
        <Card className="bg-card border-border">
          <CardHeader>
            <CardTitle className="text-foreground text-sm">Status</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="flex items-center gap-3 p-3 rounded-lg bg-muted">
              <div
                className={`w-3 h-3 rounded-full ${cameraError ? "bg-destructive" : "bg-green-500 animate-pulse"}`}
              />
              <p className="text-sm text-muted-foreground">
                {cameraError ? "Camera unavailable" : "Camera active & monitoring"}
              </p>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Present Students List */}
      <Card className="bg-card border-border">
        <CardHeader>
          <CardTitle className="text-foreground">Present Today</CardTitle>
          <p className="text-sm text-muted-foreground">{presentStudents.length} present</p>
        </CardHeader>
        <CardContent>
          <div className="space-y-2 max-h-96 overflow-y-auto">
            {presentStudents.map((student) => (
              <div
                key={student.id}
                className="p-3 rounded-lg bg-muted border border-border hover:bg-accent/10 transition-colors"
              >
                <div className="flex items-start justify-between">
                  <div>
                    <p className="text-sm font-medium text-foreground">{student.name}</p>
                    <p className="text-xs text-muted-foreground">Roll: {student.rollNo}</p>
                  </div>
                  <div className="flex flex-col items-end gap-1">
                    <Clock size={14} className="text-primary" />
                    <p className="text-xs text-muted-foreground">{student.timestamp}</p>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>
    </div>
  )
}

function Camera({ size, className }: { size: number; className?: string }) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      className={className}
    >
      <path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z" />
      <circle cx="12" cy="13" r="4" />
    </svg>
  )
}
